UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"DDAVP Clamp-Bolus Protocol","body":"**Step 1 — Lock the kidneys:**\n[Desmopressin (DDAVP)](#/drug/desmopressin/ddavp clamp) **2 mcg IV q6-8h** (schedule doses around the clock). This prevents all renal free water excretion.\n\n**Step 2 — Controlled bolus correction:**\n[3% Hypertonic Saline](#/drug/hypertonic-saline/ddavp clamp bolus) **100 mL IV bolus** — each bolus raises Na+ approximately **2 mEq/L** in a 70 kg adult. For this patient’s own estimate, use the [Sodium Change per Liter calculator](#/calculator/adrogue-madias). Give boluses every 4-6 hours as needed to achieve target correction rate.\n\n**Step 3 — Monitor:**\n• Check Na+ **every 2 hours** during active clamp\n• Track cumulative 24-hour correction on a flow sheet\n• Target: 4-6 mEq/L rise in first 24 hours for high-risk patients, up to 10 mEq/L for standard risk\n\n**Step 4 — Discontinue clamp:**\n• Once Na+ >125 mEq/L and underlying cause addressed\n• Taper: extend DDAVP interval to q12h for 24 hours, then stop\n• Continue monitoring Na+ q4-6h for 24 hours after stopping DDAVP\n\n**If Na+ rises too fast despite clamp:** Confirm DDAVP dosing is adequate (urine Osm should be >500). Give **D5W 3 mL/kg/hr** to actively lower Na+ back to safe trajectory.\n\n[DDAVP Clamp-Bolus Protocol](#/info/na-ddavp-clamp) — expanded protocol with discontinuation guidance","citation":[1,7,8],"next":"na-hypo-etiology","treatment":{"firstLine":{"drug":"Desmopressin (DDAVP)","dose":"2 mcg","route":"IV","frequency":"q6-8h","duration":"Until Na+ >125 and cause addressed","notes":"Locks kidneys in concentrating mode. Na+ rises only from 3% saline boluses."},"alternative":{"drug":"3% Hypertonic Saline","dose":"100 mL","route":"IV bolus","frequency":"q4-6h PRN","duration":"Until target correction achieved","notes":"Each bolus raises Na+ ~2 mEq/L in 70 kg adult."},"monitoring":"Check Na+ q2h during clamp. Track cumulative 24h correction. Taper DDAVP to q12h x24h before discontinuing."},"summary":"DDAVP 2mcg IV q6-8h locks kidneys; 3% NaCl 100mL boluses q4-6h for controlled correction; Na+ q2h; taper DDAVP to q12h before stopping"}'::jsonb
